pub fn compact<T: Display>(items: &[T], max: usize) -> String {
    let total = items.len();
    if total <= max {
        return items.iter().map(|i| i.to_string()).collect::<Vec<_>>().join(", ");
    }
    let head: Vec<_> = items[..max-1].iter().map(|i| i.to_string()).collect();
    format!("{}, ... and {} more", head.join(", "), total - (max - 1))
}

